*** Begin Patch
*** Add File: /workspace/go.mod
+module gron
+
+go 1.21
*** Add File: /workspace/compile.sh
+#!/usr/bin/env bash
+set -euo pipefail
+
+cd "$(dirname "$0")"
+go build -o executable .
*** Add File: /workspace/main.go
+package main
+
+import (
+	"bufio"
+	"bytes"
+	"crypto/tls"
+	"encoding/json"
+	"errors"
+	"flag"
+	"fmt"
+	"io"
+	"net/http"
+	"net/url"
+	"os"
+	"sort"
+	"strconv"
+	"strings"
+	"unicode"
+	"unicode/utf8"
+)
+
+const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable
+
+Usage:
+  gron [OPTIONS] [FILE|URL|-]
+
+Options:
+  -u, --ungron     Reverse the operation (turn assignments back into JSON)
+  -v, --values     Print just the values of provided assignments
+  -c, --colorize   Colorize output (default on tty)
+  -m, --monochrome Monochrome (don't colorize output)
+  -s, --stream     Treat each line of input as a separate JSON object
+  -k, --insecure   Disable certificate validation
+  -x, --proxy      Set proxy configuration
+      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
+  -j, --json       Represent gron data as JSON stream
+      --no-sort    Don't sort output (faster)
+      --version    Print version information
+
+Exit Codes:
+  0	OK
+  1	Failed to open file
+  2	Failed to read input
+  3	Failed to form statements
+  4	Failed to fetch URL
+  5	Failed to parse statements
+  6	Failed to encode JSON
+
+Examples:
+  gron /tmp/apiresponse.json
+  gron http://jsonplaceholder.typicode.com/users/1 
+  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
+  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
+`
+
+type options struct {
+	ungron     bool
+	values     bool
+	colorize   bool
+	monochrome bool
+	stream     bool
+	insecure   bool
+	proxy      string
+	noProxy    string
+	json       bool
+	noSort     bool
+	version    bool
+}
+
+type inputSource struct {
+	reader  io.ReadCloser
+	fromURL bool
+}
+
+type segmentKind int
+
+const (
+	segmentKey segmentKind = iota
+	segmentIndex
+)
+
+type pathSegment struct {
+	kind     segmentKind
+	key      string
+	index    int
+	rendered string
+}
+
+type flatStatement struct {
+	path  []pathSegment
+	value any
+}
+
+type missingValue struct{}
+
+var (
+	missingToken = missingValue{}
+	reservedWords = map[string]struct{}{
+		"await": {}, "break": {}, "case": {}, "catch": {}, "class": {}, "const": {},
+		"continue": {}, "debugger": {}, "default": {}, "delete": {}, "do": {}, "else": {},
+		"enum": {}, "export": {}, "extends": {}, "false": {}, "finally": {}, "for": {},
+		"function": {}, "if": {}, "implements": {}, "import": {}, "in": {}, "instanceof": {},
+		"interface": {}, "let": {}, "new": {}, "null": {}, "package": {}, "private": {},
+		"protected": {}, "public": {}, "return": {}, "static": {}, "super": {}, "switch": {},
+		"this": {}, "throw": {}, "true": {}, "try": {}, "typeof": {}, "var": {}, "void": {},
+		"while": {}, "with": {}, "yield": {},
+	}
+)
+
+func main() {
+	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
+}
+
+func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
+	opts, source, code, ok := parseFlags(args, stderr)
+	if !ok {
+		return code
+	}
+
+	if opts.version {
+		_, _ = fmt.Fprintln(stdout, "gron version dev")
+		return 0
+	}
+
+	if opts.ungron {
+		return runUngron(opts, source, stdin, stdout, stderr)
+	}
+
+	if opts.values {
+		return runValues(stdin, stdout)
+	}
+
+	return runGron(opts, source, stdin, stdout, stderr)
+}
+
+func parseFlags(args []string, stderr io.Writer) (options, string, int, bool) {
+	var opts options
+
+	fs := flag.NewFlagSet("gron", flag.ContinueOnError)
+	fs.SetOutput(io.Discard)
+	fs.BoolVar(&opts.ungron, "u", false, "")
+	fs.BoolVar(&opts.ungron, "ungron", false, "")
+	fs.BoolVar(&opts.values, "v", false, "")
+	fs.BoolVar(&opts.values, "values", false, "")
+	fs.BoolVar(&opts.colorize, "c", false, "")
+	fs.BoolVar(&opts.colorize, "colorize", false, "")
+	fs.BoolVar(&opts.monochrome, "m", false, "")
+	fs.BoolVar(&opts.monochrome, "monochrome", false, "")
+	fs.BoolVar(&opts.stream, "s", false, "")
+	fs.BoolVar(&opts.stream, "stream", false, "")
+	fs.BoolVar(&opts.insecure, "k", false, "")
+	fs.BoolVar(&opts.insecure, "insecure", false, "")
+	fs.StringVar(&opts.proxy, "x", "", "")
+	fs.StringVar(&opts.proxy, "proxy", "", "")
+	fs.StringVar(&opts.noProxy, "noproxy", "", "")
+	fs.BoolVar(&opts.json, "j", false, "")
+	fs.BoolVar(&opts.json, "json", false, "")
+	fs.BoolVar(&opts.noSort, "no-sort", false, "")
+	fs.BoolVar(&opts.version, "version", false, "")
+
+	if err := fs.Parse(args); err != nil {
+		if errors.Is(err, flag.ErrHelp) {
+			_, _ = io.WriteString(stderr, helpText)
+			return options{}, "", 0, false
+		}
+
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		_, _ = io.WriteString(stderr, helpText)
+		return options{}, "", 2, false
+	}
+
+	source := ""
+	if fs.NArg() > 0 {
+		source = fs.Arg(0)
+	}
+
+	return opts, source, 0, true
+}
+
+func runValues(stdin io.Reader, stdout io.Writer) int {
+	scanner := newScanner(stdin)
+	for scanner.Scan() {
+		stmt, ok, _, err := parseAssignmentLine(scanner.Text())
+		if err != nil || !ok {
+			continue
+		}
+
+		switch value := stmt.value.(type) {
+		case string:
+			_, _ = fmt.Fprintln(stdout, value)
+		case json.Number:
+			_, _ = fmt.Fprintln(stdout, value.String())
+		case bool:
+			_, _ = fmt.Fprintln(stdout, strconv.FormatBool(value))
+		case nil:
+			_, _ = fmt.Fprintln(stdout, "null")
+		}
+	}
+
+	return 0
+}
+
+func runGron(opts options, source string, stdin io.Reader, stdout, stderr io.Writer) int {
+	input, code, err := openInput(source, stdin, opts)
+	if err != nil {
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		return code
+	}
+	defer input.reader.Close()
+
+	if opts.stream {
+		return gronStream(input, opts, stdout, stderr)
+	}
+
+	value, err := decodeJSONValue(input.reader)
+	if err != nil {
+		_, _ = fmt.Fprintf(stderr, "failed to form statements: %v\n", err)
+		return 3
+	}
+
+	statements := flattenValue(value, nil)
+	if !opts.noSort {
+		sortStatements(statements)
+	}
+
+	for _, stmt := range statements {
+		if err := writeStatement(stdout, stmt, opts.json); err != nil {
+			_, _ = fmt.Fprintln(stderr, err.Error())
+			return 6
+		}
+	}
+
+	return 0
+}
+
+func gronStream(input *inputSource, opts options, stdout, stderr io.Writer) int {
+	root := flatStatement{path: nil, value: []any{}}
+	if err := writeStatement(stdout, root, opts.json); err != nil {
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		return 6
+	}
+
+	scanner := newScanner(input.reader)
+	index := 0
+	for scanner.Scan() {
+		value, err := decodeJSONValue(strings.NewReader(scanner.Text()))
+		if err != nil {
+			_, _ = fmt.Fprintf(stderr, "failed to form statements: %v\n", err)
+			return 3
+		}
+
+		prefix := []pathSegment{indexSegment(index)}
+		statements := flattenValue(value, prefix)
+		if !opts.noSort {
+			sortStatements(statements)
+		}
+
+		for _, stmt := range statements {
+			if err := writeStatement(stdout, stmt, opts.json); err != nil {
+				_, _ = fmt.Fprintln(stderr, err.Error())
+				return 6
+			}
+		}
+
+		index++
+	}
+
+	if err := scanner.Err(); err != nil {
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		if input.fromURL {
+			return 4
+		}
+		return 2
+	}
+
+	return 0
+}
+
+func runUngron(opts options, source string, stdin io.Reader, stdout, stderr io.Writer) int {
+	input, code, err := openInput(source, stdin, opts)
+	if err != nil {
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		return code
+	}
+	defer input.reader.Close()
+
+	var value any
+	var parsed bool
+
+	if opts.json {
+		value, parsed, err = parseJSONStream(input.reader)
+		if err != nil {
+			_, _ = fmt.Fprintln(stderr, err.Error())
+			return 5
+		}
+	} else {
+		value, parsed, err = parseAssignments(input.reader)
+		if err != nil {
+			_, _ = fmt.Fprintln(stderr, err.Error())
+			return 5
+		}
+	}
+
+	if !parsed {
+		_, _ = fmt.Fprintln(stderr, "no statements were parsed")
+		return 5
+	}
+
+	value = materialize(value)
+	if err := writeIndentedJSON(stdout, value); err != nil {
+		_, _ = fmt.Fprintln(stderr, err.Error())
+		return 6
+	}
+
+	return 0
+}
+
+func parseAssignments(reader io.Reader) (any, bool, error) {
+	scanner := newScanner(reader)
+	var result any
+	parsed := false
+
+	for scanner.Scan() {
+		stmt, ok, display, err := parseAssignmentLine(scanner.Text())
+		if err != nil {
+			return nil, false, fmt.Errorf("ungron failed for `%s`: %v", display, err)
+		}
+		if !ok {
+			continue
+		}
+
+		partial := buildTree(stmt.path, stmt.value)
+		if !parsed {
+			result = partial
+			parsed = true
+			continue
+		}
+
+		result, err = merge(result, partial)
+		if err != nil {
+			return nil, false, fmt.Errorf("failed to merge statements: %v", err)
+		}
+	}
+
+	if err := scanner.Err(); err != nil {
+		return nil, false, err
+	}
+
+	return result, parsed, nil
+}
+
+func parseJSONStream(reader io.Reader) (any, bool, error) {
+	scanner := newScanner(reader)
+	var result any
+	parsed := false
+
+	for scanner.Scan() {
+		stmt, err := parseJSONStreamLine(scanner.Text())
+		if err != nil {
+			return nil, false, err
+		}
+
+		partial := buildTree(stmt.path, stmt.value)
+		if !parsed {
+			result = partial
+			parsed = true
+			continue
+		}
+
+		result, err = merge(result, partial)
+		if err != nil {
+			return nil, false, fmt.Errorf("failed to merge statements: %v", err)
+		}
+	}
+
+	if err := scanner.Err(); err != nil {
+		return nil, false, err
+	}
+
+	return result, parsed, nil
+}
+
+func flattenValue(value any, path []pathSegment) []flatStatement {
+	statements := []flatStatement{{path: append([]pathSegment(nil), path...), value: statementValue(value)}}
+
+	switch typed := value.(type) {
+	case map[string]any:
+		for key, child := range typed {
+			childPath := append(copyPath(path), keySegment(key))
+			statements = append(statements, flattenValue(child, childPath)...)
+		}
+	case []any:
+		for index, child := range typed {
+			childPath := append(copyPath(path), indexSegment(index))
+			statements = append(statements, flattenValue(child, childPath)...)
+		}
+	}
+
+	return statements
+}
+
+func sortStatements(statements []flatStatement) {
+	sort.Slice(statements, func(i, j int) bool {
+		return comparePaths(statements[i].path, statements[j].path) < 0
+	})
+}
+
+func comparePaths(left, right []pathSegment) int {
+	limit := len(left)
+	if len(right) < limit {
+		limit = len(right)
+	}
+
+	for i := 0; i < limit; i++ {
+		if left[i].kind == segmentIndex && right[i].kind == segmentIndex {
+			switch {
+			case left[i].index < right[i].index:
+				return -1
+			case left[i].index > right[i].index:
+				return 1
+			default:
+				continue
+			}
+		}
+
+		if cmp := strings.Compare(left[i].rendered, right[i].rendered); cmp != 0 {
+			return cmp
+		}
+	}
+
+	switch {
+	case len(left) < len(right):
+		return -1
+	case len(left) > len(right):
+		return 1
+	default:
+		return 0
+	}
+}
+
+func writeStatement(writer io.Writer, stmt flatStatement, jsonMode bool) error {
+	if jsonMode {
+		path := make([]any, 0, len(stmt.path))
+		for _, segment := range stmt.path {
+			if segment.kind == segmentIndex {
+				path = append(path, segment.index)
+			} else {
+				path = append(path, segment.key)
+			}
+		}
+
+		line, err := marshalCompact([]any{path, stmt.value})
+		if err != nil {
+			return err
+		}
+		_, err = fmt.Fprintln(writer, line)
+		return err
+	}
+
+	line, err := marshalCompact(stmt.value)
+	if err != nil {
+		return err
+	}
+	_, err = fmt.Fprintf(writer, "%s = %s;\n", renderPath(stmt.path), line)
+	return err
+}
+
+func renderPath(path []pathSegment) string {
+	var builder strings.Builder
+	builder.WriteString("json")
+	for _, segment := range path {
+		builder.WriteString(segment.rendered)
+	}
+	return builder.String()
+}
+
+func statementValue(value any) any {
+	switch value.(type) {
+	case map[string]any:
+		return map[string]any{}
+	case []any:
+		return []any{}
+	default:
+		return value
+	}
+}
+
+func decodeJSONValue(reader io.Reader) (any, error) {
+	decoder := json.NewDecoder(reader)
+	decoder.UseNumber()
+
+	var value any
+	if err := decoder.Decode(&value); err != nil {
+		return nil, err
+	}
+
+	return value, nil
+}
+
+func marshalCompact(value any) (string, error) {
+	var buffer bytes.Buffer
+	encoder := json.NewEncoder(&buffer)
+	encoder.SetEscapeHTML(false)
+	if err := encoder.Encode(value); err != nil {
+		return "", err
+	}
+	return strings.TrimSuffix(buffer.String(), "\n"), nil
+}
+
+func writeIndentedJSON(writer io.Writer, value any) error {
+	encoder := json.NewEncoder(writer)
+	encoder.SetEscapeHTML(false)
+	encoder.SetIndent("", "  ")
+	return encoder.Encode(value)
+}
+
+func openInput(source string, stdin io.Reader, opts options) (*inputSource, int, error) {
+	if source == "" || source == "-" {
+		return &inputSource{reader: io.NopCloser(stdin)}, 0, nil
+	}
+
+	if strings.HasPrefix(source, "http://") || strings.HasPrefix(source, "https://") {
+		client, err := buildHTTPClient(opts)
+		if err != nil {
+			return nil, 4, err
+		}
+
+		req, err := http.NewRequest(http.MethodGet, source, nil)
+		if err != nil {
+			return nil, 4, err
+		}
+		req.Header.Set("User-Agent", "gron/dev")
+
+		resp, err := client.Do(req)
+		if err != nil {
+			return nil, 4, err
+		}
+
+		return &inputSource{reader: resp.Body, fromURL: true}, 0, nil
+	}
+
+	file, err := os.Open(source)
+	if err != nil {
+		return nil, 1, err
+	}
+	return &inputSource{reader: file}, 0, nil
+}
+
+func buildHTTPClient(opts options) (*http.Client, error) {
+	transport := http.DefaultTransport.(*http.Transport).Clone()
+	if opts.insecure {
+		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
+	}
+
+	proxyFunc, err := buildProxyFunc(opts)
+	if err != nil {
+		return nil, err
+	}
+	transport.Proxy = proxyFunc
+
+	return &http.Client{Transport: transport}, nil
+}
+
+func buildProxyFunc(opts options) (func(*http.Request) (*url.URL, error), error) {
+	noProxy := parseNoProxy(opts.noProxy)
+	if opts.proxy == "" {
+		return func(req *http.Request) (*url.URL, error) {
+			if _, ok := noProxy[req.URL.Host]; ok {
+				return nil, nil
+			}
+			return http.ProxyFromEnvironment(req)
+		}, nil
+	}
+
+	proxyURL, err := url.Parse(opts.proxy)
+	if err != nil {
+		return nil, err
+	}
+
+	return func(req *http.Request) (*url.URL, error) {
+		if _, ok := noProxy[req.URL.Host]; ok {
+			return nil, nil
+		}
+		return proxyURL, nil
+	}, nil
+}
+
+func parseNoProxy(value string) map[string]struct{} {
+	out := map[string]struct{}{}
+	if value == "" {
+		return out
+	}
+
+	for _, part := range strings.Split(value, ",") {
+		part = strings.TrimSpace(part)
+		if part != "" {
+			out[part] = struct{}{}
+		}
+	}
+
+	return out
+}
+
+type parsedStatement struct {
+	path  []pathSegment
+	value any
+}
+
+func parseAssignmentLine(line string) (parsedStatement, bool, string, error) {
+	if !strings.HasPrefix(line, "json") {
+		return parsedStatement{}, false, "", nil
+	}
+
+	path, pos, display, ok, err := parseAssignmentPath(line)
+	if !ok || err != nil {
+		return parsedStatement{}, ok, display, err
+	}
+
+	if !strings.HasPrefix(line[pos:], " = ") {
+		return parsedStatement{}, false, "", nil
+	}
+
+	valueText := line[pos+3:]
+	if !strings.HasSuffix(valueText, ";") {
+		return parsedStatement{}, true, line, errors.New("statement has no value")
+	}
+
+	valueText = valueText[:len(valueText)-1]
+	value, err := decodeJSONValue(strings.NewReader(valueText))
+	if err != nil {
+		return parsedStatement{}, true, line, fmt.Errorf("invalid value `%s`", valueText)
+	}
+
+	return parsedStatement{path: path, value: value}, true, line, nil
+}
+
+func parseAssignmentPath(line string) ([]pathSegment, int, string, bool, error) {
+	pos := len("json")
+	path := []pathSegment{}
+
+	for {
+		if strings.HasPrefix(line[pos:], " = ") {
+			return path, pos, line[:pos], true, nil
+		}
+		if pos >= len(line) {
+			return nil, pos, line, false, nil
+		}
+
+		switch line[pos] {
+		case '.':
+			segment, next, err := parseDotSegment(line, pos)
+			if err != nil {
+				return nil, next, line[:next], true, err
+			}
+			path = append(path, segment)
+			pos = next
+		case '[':
+			segment, next, display, err := parseBracketSegment(line, pos)
+			if err != nil {
+				return nil, next, display, true, err
+			}
+			path = append(path, segment)
+			pos = next
+		default:
+			return nil, pos, "", false, nil
+		}
+	}
+}
+
+func parseDotSegment(line string, start int) (pathSegment, int, error) {
+	pos := start + 1
+	if pos >= len(line) {
+		return pathSegment{}, pos, errors.New("invalid statement")
+	}
+
+	first := true
+	for pos < len(line) {
+		r, size := utf8.DecodeRuneInString(line[pos:])
+		if !isIdentifierRune(r, first) {
+			break
+		}
+		first = false
+		pos += size
+	}
+
+	if first {
+		return pathSegment{}, pos, errors.New("invalid statement")
+	}
+
+	key := line[start+1 : pos]
+	return pathSegment{
+		kind:     segmentKey,
+		key:      key,
+		rendered: "." + key,
+	}, pos, nil
+}
+
+func parseBracketSegment(line string, start int) (pathSegment, int, string, error) {
+	if start+1 >= len(line) {
+		return pathSegment{}, start + 1, line[:start+1], errors.New("invalid statement")
+	}
+
+	if line[start+1] == '"' {
+		end, ok := findJSONStringEnd(line, start+1)
+		if !ok {
+			return pathSegment{}, len(line), line, errors.New("invalid statement")
+		}
+
+		if end+1 >= len(line) || line[end+1] != ']' {
+			return pathSegment{}, len(line), line, errors.New("invalid statement")
+		}
+
+		var key string
+		if err := json.Unmarshal([]byte(line[start+1:end+1]), &key); err != nil {
+			return pathSegment{}, len(line), line, errors.New("invalid statement")
+		}
+
+		return pathSegment{
+			kind:     segmentKey,
+			key:      key,
+			rendered: renderKey(key),
+		}, end + 2, line[:end+2], nil
+	}
+
+	pos := start + 1
+	for pos < len(line) && line[pos] >= '0' && line[pos] <= '9' {
+		pos++
+	}
+	if pos == start+1 || pos >= len(line) || line[pos] != ']' {
+		return pathSegment{}, pos, line[:start+1], errors.New("invalid statement")
+	}
+
+	index, err := strconv.Atoi(line[start+1 : pos])
+	if err != nil {
+		return pathSegment{}, pos, line[:start+1], errors.New("invalid statement")
+	}
+
+	return pathSegment{
+		kind:     segmentIndex,
+		index:    index,
+		rendered: fmt.Sprintf("[%d]", index),
+	}, pos + 1, line[:pos+1], nil
+}
+
+func findJSONStringEnd(line string, start int) (int, bool) {
+	pos := start + 1
+	for pos < len(line) {
+		switch line[pos] {
+		case '\\':
+			pos += 2
+		case '"':
+			return pos, true
+		default:
+			pos++
+		}
+	}
+	return 0, false
+}
+
+func parseJSONStreamLine(line string) (parsedStatement, error) {
+	var pair []any
+	decoder := json.NewDecoder(strings.NewReader(line))
+	decoder.UseNumber()
+	if err := decoder.Decode(&pair); err != nil {
+		return parsedStatement{}, err
+	}
+	if len(pair) != 2 {
+		return parsedStatement{}, errors.New("invalid statement")
+	}
+
+	rawPath, ok := pair[0].([]any)
+	if !ok {
+		return parsedStatement{}, errors.New("invalid statement")
+	}
+
+	path := make([]pathSegment, 0, len(rawPath))
+	for _, item := range rawPath {
+		switch value := item.(type) {
+		case string:
+			path = append(path, keySegment(value))
+		case json.Number:
+			index, err := strconv.Atoi(value.String())
+			if err != nil {
+				return parsedStatement{}, errors.New("invalid statement")
+			}
+			path = append(path, indexSegment(index))
+		default:
+			return parsedStatement{}, errors.New("invalid statement")
+		}
+	}
+
+	return parsedStatement{path: path, value: pair[1]}, nil
+}
+
+func buildTree(path []pathSegment, value any) any {
+	if len(path) == 0 {
+		return value
+	}
+
+	head := path[0]
+	tail := path[1:]
+
+	if head.kind == segmentIndex {
+		array := make([]any, head.index+1)
+		for i := range array {
+			array[i] = missingToken
+		}
+		array[head.index] = buildTree(tail, value)
+		return array
+	}
+
+	return map[string]any{
+		head.key: buildTree(tail, value),
+	}
+}
+
+func merge(left, right any) (any, error) {
+	if isMissing(left) {
+		return right, nil
+	}
+	if isMissing(right) {
+		return left, nil
+	}
+
+	leftMap, leftIsMap := left.(map[string]any)
+	rightMap, rightIsMap := right.(map[string]any)
+	if leftIsMap {
+		if !rightIsMap {
+			return nil, errors.New("cannot merge object with non-object")
+		}
+		return mergeMaps(leftMap, rightMap)
+	}
+	if rightIsMap {
+		return right, nil
+	}
+
+	leftArray, leftIsArray := left.([]any)
+	rightArray, rightIsArray := right.([]any)
+	if leftIsArray {
+		if !rightIsArray {
+			return nil, errors.New("cannot merge array with non-array")
+		}
+		return mergeArrays(leftArray, rightArray)
+	}
+	if rightIsArray {
+		return right, nil
+	}
+
+	return right, nil
+}
+
+func mergeMaps(left, right map[string]any) (any, error) {
+	out := make(map[string]any, len(left)+len(right))
+	for key, value := range left {
+		out[key] = value
+	}
+	for key, value := range right {
+		current, ok := out[key]
+		if !ok {
+			out[key] = value
+			continue
+		}
+
+		merged, err := merge(current, value)
+		if err != nil {
+			return nil, err
+		}
+		out[key] = merged
+	}
+	return out, nil
+}
+
+func mergeArrays(left, right []any) (any, error) {
+	size := len(left)
+	if len(right) > size {
+		size = len(right)
+	}
+
+	out := make([]any, size)
+	for i := range out {
+		out[i] = missingToken
+	}
+
+	for i, value := range left {
+		out[i] = value
+	}
+
+	for i, value := range right {
+		merged, err := merge(out[i], value)
+		if err != nil {
+			return nil, err
+		}
+		out[i] = merged
+	}
+
+	return out, nil
+}
+
+func materialize(value any) any {
+	switch typed := value.(type) {
+	case map[string]any:
+		out := make(map[string]any, len(typed))
+		for key, child := range typed {
+			out[key] = materialize(child)
+		}
+		return out
+	case []any:
+		out := make([]any, len(typed))
+		for i, child := range typed {
+			if isMissing(child) {
+				out[i] = nil
+			} else {
+				out[i] = materialize(child)
+			}
+		}
+		return out
+	default:
+		return value
+	}
+}
+
+func keySegment(key string) pathSegment {
+	return pathSegment{
+		kind:     segmentKey,
+		key:      key,
+		rendered: renderKey(key),
+	}
+}
+
+func indexSegment(index int) pathSegment {
+	return pathSegment{
+		kind:     segmentIndex,
+		index:    index,
+		rendered: fmt.Sprintf("[%d]", index),
+	}
+}
+
+func renderKey(key string) string {
+	if isIdentifierString(key) && !isReservedWord(key) {
+		return "." + key
+	}
+
+	encoded, err := marshalCompact(key)
+	if err != nil {
+		return "." + key
+	}
+	return "[" + encoded + "]"
+}
+
+func isIdentifierString(value string) bool {
+	if value == "" {
+		return false
+	}
+
+	first := true
+	for _, r := range value {
+		if !isIdentifierRune(r, first) {
+			return false
+		}
+		first = false
+	}
+
+	return true
+}
+
+func isIdentifierRune(r rune, first bool) bool {
+	if r == '$' || r == '_' {
+		return true
+	}
+	if unicode.IsLetter(r) {
+		return true
+	}
+	if !first && unicode.IsDigit(r) {
+		return true
+	}
+	return false
+}
+
+func isReservedWord(value string) bool {
+	_, ok := reservedWords[value]
+	return ok
+}
+
+func copyPath(path []pathSegment) []pathSegment {
+	if len(path) == 0 {
+		return nil
+	}
+	out := make([]pathSegment, len(path))
+	copy(out, path)
+	return out
+}
+
+func isMissing(value any) bool {
+	_, ok := value.(missingValue)
+	return ok
+}
+
+func newScanner(reader io.Reader) *bufio.Scanner {
+	scanner := bufio.NewScanner(reader)
+	scanner.Buffer(make([]byte, 1024), 1024*1024*16)
+	return scanner
+}
